const adapter = globalThis.__ai4a11yRuntime?.adapters?.preview?.adapter;
const isEnabled = adapter && adapter.s && !adapter.s.ended;
if (!isEnabled) return true;

let lateShift = 0;
let observer = null;
try {
  observer = new PerformanceObserver((list) => {
    for (const entry of list.getEntries()) {
      if (!entry.hadRecentInput) lateShift += entry.value;
    }
  });
  observer.observe({ type: 'layout-shift', buffered: false });
} catch (_) {}

await new Promise(r => setTimeout(r, 120));
if (observer) observer.disconnect();

return lateShift === 0;
